param([Parameter(Mandatory=$true)][string]$Root,[Parameter(Mandatory=$true)][string]$SetStartIso,[Parameter(Mandatory=$true)][string]$SetEndIso,[Parameter(Mandatory=$true)][string]$ExpectedClub)
$ErrorActionPreference='SilentlyContinue'
$out=Join-Path $Root 'UltimateCoach';New-Item -ItemType Directory -Path $out -Force|Out-Null
$start=[datetimeoffset]::Parse($SetStartIso).LocalDateTime;$end=[datetimeoffset]::Parse($SetEndIso).LocalDateTime
$log=Join-Path $env:LOCALAPPDATA 'SwingNerdsClip\gspro_shots.log';$arr=@();if(Test-Path $log){foreach($line in (Get-Content $log -Tail 1800)){if($line -match '^\[(?<ts>[0-9\-: .]+)\] \[LastShot #(?<num>\d+)\] (?<json>\{.*\})$'){try{$ts=[datetime]::Parse($matches['ts']);if($ts -ge $start -and $ts -lt $end){$j=$matches['json']|ConvertFrom-Json;if([string]$j.club -eq $ExpectedClub){$arr += [pscustomobject]@{shot=[int]$matches['num'];time=$ts.ToString('o');club=[string]$j.club;carry=$(if($null-ne$j.Carry){[math]::Round([double]$j.Carry,1)}else{$null});total=$(if($null-ne$j.Total){[math]::Round([double]$j.Total,1)}elseif($null-ne$j.TotalDistance){[math]::Round([double]$j.TotalDistance,1)}else{$null});ball_speed=$(if($null-ne$j.BallSpeed){[math]::Round([double]$j.BallSpeed,1)}else{$null});back_spin=$(if($null-ne$j.BackSpin){[math]::Round([double]$j.BackSpin,0)}else{$null});side_spin=$(if($null-ne$j.SideSpin){[math]::Round([double]$j.SideSpin,0)}else{$null});hla=$(if($null-ne$j.HLA){[math]::Round([double]$j.HLA,1)}else{$null});vla=$(if($null-ne$j.VLA){[math]::Round([double]$j.VLA,1)}else{$null});offline=$(if($null-ne$j.Offline){[math]::Round([double]$j.Offline,1)}else{$null});spin_axis=$(if($null-ne$j.rawSpinAxis){[math]::Round([double]$j.rawSpinAxis,1)}else{$null});club_speed=$(if($j.ClubSpeed -and [double]$j.ClubSpeed-gt0){[math]::Round([double]$j.ClubSpeed,1)}else{$null});path=$(if($null-ne$j.Path -and [math]::Abs([double]$j.Path)-lt25){[math]::Round([double]$j.Path,1)}else{$null});aoa=$(if($null-ne$j.AoA -and [math]::Abs([double]$j.AoA)-lt25){[math]::Round([double]$j.AoA,1)}else{$null});smash=$(if($j.SmashFactor -and [double]$j.SmashFactor-gt0){[math]::Round([double]$j.SmashFactor,2)}else{$null})}}}}catch{}}}}
if($arr.Count -gt 0){$file=Join-Path $out ('coach_set_autoclosed_'+(Get-Date -Format 'yyyyMMdd_HHmmss')+'_'+($ExpectedClub-replace'[^A-Za-z0-9_-]','_')+'.json');[ordered]@{request_id='autoclosed';set_started=$SetStartIso;set_ended=$SetEndIso;shot_count=$arr.Count;shots=@($arr|Sort-Object shot -Unique);swingnerds=@();archive_reason='Club changed before the user requested coaching.'}|ConvertTo-Json -Depth 12|Set-Content $file -Encoding UTF8}
